"""fig_qp.svg: channel -> QP mapping of comm::get_qp_mode for the source's own example (3 SMs, 10 QPs, no notify
warps): SM s owns QPs s, s+3, s+6, ...; channel j of SM s uses QP s + (j mod n_s) * 3, CTA-exclusive.
deep_ep/include/deep_ep/comm/barrier.cuh lines 57-86 (main)."""
import os
W, H = 480, 200
LX, CW, X0 = 70, 40, 74
rows = 3
o = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}pt" height="{H}pt" viewBox="0 0 {W} {H}" font-family="Helvetica, Arial, sans-serif">',
     '  <!-- fig_qp (generated by gen_qp.py) -->']
o.append('  <text x="62" y="31" text-anchor="end" font-size="18" font-weight="bold" fill="#595959">QP</text>')
for q in range(10):
    x = X0 + CW * q
    o.append(f'  <text x="{x + CW / 2}" y="31" text-anchor="middle" font-size="18" font-family="Menlo, \'Courier New\', monospace" fill="#222222">{q}</text>')
for s in range(rows):
    y = 44 + 50 * s
    o.append(f'  <text x="62" y="{y + 28}" text-anchor="end" font-size="18" font-weight="bold" fill="#1F4E79">SM {s}</text>')
    owned = [q for q in range(10) if q % 3 == s]
    for q in range(10):
        x = X0 + CW * q
        if q in owned:
            j = owned.index(q)
            o.append(f'  <rect x="{x + 2}" y="{y}" width="{CW - 4}" height="42" rx="3" fill="#DEEBF7" stroke="#1F4E79" stroke-width="1.5"/>')
            o.append(f'  <text x="{x + CW / 2}" y="{y + 26.5}" text-anchor="middle" font-size="15" fill="#1F4E79">c{j}</text>')
        else:
            o.append(f'  <rect x="{x + 2}" y="{y}" width="{CW - 4}" height="42" rx="3" fill="#FFFFFF" stroke="#BFBFBF" stroke-width="1" stroke-dasharray="3,3"/>')
o.append('</svg>')
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "fig_qp.svg"), "w").write("\n".join(o) + "\n")
print("ok")
